import{_ as a,o as e,c as l,ag as d}from"./chunks/framework.CmaAMB6e.js";const b=JSON.parse('{"title":"Agent 学习等级体系（L1-L5）","description":"","frontmatter":{},"headers":[],"relativePath":"agent/levels.md","filePath":"agent/levels.md","lastUpdated":null}'),r={name:"agent/levels.md"};function i(h,t,o,n,s,u){return e(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="agent-学习等级体系-l1-l5" tabindex="-1">Agent 学习等级体系（L1-L5） <a class="header-anchor" href="#agent-学习等级体系-l1-l5" aria-label="Permalink to &quot;Agent 学习等级体系（L1-L5）&quot;">​</a></h1><blockquote><p>每个技能独立走 5 级阶梯。等级衡量的是「能做什么」,不是「背过什么」。每学完一级用 <code>/assess agent &lt;等级&gt;</code> 让 AI 考核,达标后再进下一级。</p><p>等级 ↔ 阶段映射以 <code>learning-path.md</code> 为准;本文件定义每级的<strong>能力目标、常见错误、晋升标准、考核题型</strong>。</p></blockquote><h2 id="等级总览" tabindex="-1">等级总览 <a class="header-anchor" href="#等级总览" aria-label="Permalink to &quot;等级总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>等级</th><th>名称</th><th>定位</th><th>对应阶段</th><th>考核最低分</th></tr></thead><tbody><tr><td>L1</td><td>新手入门</td><td>能稳定调用模型、拿到可解析的输出</td><td>阶段 1 · 基础层</td><td>80%</td></tr><tr><td>L2</td><td>工具使用者</td><td>能为 Agent 接上工具并跑通调用循环</td><td>阶段 2 · 工具能力层</td><td>80%</td></tr><tr><td>L3</td><td>应用开发者</td><td>能做 RAG 与记忆,让 Agent 基于自有数据工作</td><td>阶段 3 · 知识记忆层</td><td>80%</td></tr><tr><td>L4</td><td>资深开发者</td><td>能设计 Agent 架构,控制流程、失败与成本</td><td>阶段 4 + 阶段 5 前段</td><td>82%</td></tr><tr><td>L5</td><td>专家/架构师</td><td>能把 Agent 做成可上线、可度量、可演进的产品</td><td>阶段 5 后段 + 综合实战</td><td>85%</td></tr></tbody></table><hr><h2 id="level-1-·-新手入门" tabindex="-1">Level 1 · 新手入门 <a class="header-anchor" href="#level-1-·-新手入门" aria-label="Permalink to &quot;Level 1 · 新手入门&quot;">​</a></h2><h3 id="能力目标" tabindex="-1">能力目标 <a class="header-anchor" href="#能力目标" aria-label="Permalink to &quot;能力目标&quot;">​</a></h3><ul><li>说清 LLM 的能力边界:它是什么、不是什么</li><li>能调用 OpenAI/Anthropic API 完成基础问答</li><li>理解 token、上下文窗口、temperature 的实际影响</li><li>写出结构清晰的 Prompt,并让模型稳定返回 JSON</li><li>能统计一次调用的成本</li></ul><h3 id="常见错误" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误" aria-label="Permalink to &quot;常见错误&quot;">​</a></h3><ul><li>把 temperature 留默认值就上工具调用场景,导致输出格式飘</li><li>把规则全塞在 user message 里,而不是 system message</li><li>用正则硬解析模型输出,而不是用 JSON Mode / Schema 约束</li><li>认为「模型知道我的业务数据」</li><li>不看 token 用量,月底账单惊吓</li></ul><h3 id="晋升标准" tabindex="-1">晋升标准 <a class="header-anchor" href="#晋升标准" aria-label="Permalink to &quot;晋升标准&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>标准</th></tr></thead><tbody><tr><td>API 调用</td><td>能独立完成一次带参数配置的调用,并解释每个参数的作用</td></tr><tr><td>结构化输出</td><td>用 Pydantic + instructor 定义 Schema,连续 20 次调用零解析失败</td></tr><tr><td>Prompt</td><td>给出的 Prompt 包含角色、任务、约束、格式四要素</td></tr><tr><td>成本意识</td><td>能算出一次调用花了多少钱</td></tr></tbody></table><h3 id="考核题型" tabindex="-1">考核题型 <a class="header-anchor" href="#考核题型" aria-label="Permalink to &quot;考核题型&quot;">​</a></h3><p>概念题(30%) + 代码改错题(40%) + 实操题(30%:实现一个「从文本中抽取结构化字段」的小工具)</p><hr><h2 id="level-2-·-工具使用者" tabindex="-1">Level 2 · 工具使用者 <a class="header-anchor" href="#level-2-·-工具使用者" aria-label="Permalink to &quot;Level 2 · 工具使用者&quot;">​</a></h2><h3 id="能力目标-1" tabindex="-1">能力目标 <a class="header-anchor" href="#能力目标-1" aria-label="Permalink to &quot;能力目标&quot;">​</a></h3><ul><li>理解 Function Calling 的协议本质:模型只输出「意图」,执行在你手里</li><li>能为工具写对模型友好的描述与 JSON Schema</li><li>能实现完整的「决策 → 调工具 → 回灌观察 → 再决策」循环</li><li>能做工具的错误处理,让错误信息能指导模型自纠</li><li>理解文件/Shell/代码执行类操作的风险边界</li></ul><h3 id="常见错误-1" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误-1" aria-label="Permalink to &quot;常见错误&quot;">​</a></h3><ul><li>工具描述写成代码注释风格,模型看不懂什么时候该用</li><li>工具返回的错误信息太简单(如 <code>&quot;error&quot;</code>),模型无法自纠</li><li>不设工具数量上限,一次性给 30 个工具,选择准确率骤降</li><li>不做路径白名单,让 Agent 能删任意文件</li><li>长输出不截断,一次结果撑爆上下文</li></ul><h3 id="晋升标准-1" tabindex="-1">晋升标准 <a class="header-anchor" href="#晋升标准-1" aria-label="Permalink to &quot;晋升标准&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>标准</th></tr></thead><tbody><tr><td>工具定义</td><td>独立写出 3 个工具的 Schema 与描述,描述能让模型正确选择</td></tr><tr><td>循环实现</td><td>手写(不依赖框架)一个能跑通多轮工具调用的循环</td></tr><tr><td>错误处理</td><td>工具失败时,模型能根据错误信息调整参数重试成功</td></tr><tr><td>安全边界</td><td>能说明文件/Shell 类工具的至少 3 条防护规则</td></tr></tbody></table><h3 id="考核题型-1" tabindex="-1">考核题型 <a class="header-anchor" href="#考核题型-1" aria-label="Permalink to &quot;考核题型&quot;">​</a></h3><p>概念题(25%) + 场景设计题(35%:给定需求设计工具集) + 实操题(40%:实现一个多工具 Agent)</p><hr><h2 id="level-3-·-应用开发者" tabindex="-1">Level 3 · 应用开发者 <a class="header-anchor" href="#level-3-·-应用开发者" aria-label="Permalink to &quot;Level 3 · 应用开发者&quot;">​</a></h2><h3 id="能力目标-2" tabindex="-1">能力目标 <a class="header-anchor" href="#能力目标-2" aria-label="Permalink to &quot;能力目标&quot;">​</a></h3><ul><li>理解 Embedding 与向量检索的原理与适用边界</li><li>能搭建完整 RAG 流水线,并知道切分策略的影响</li><li>能用混合检索 + rerank 优化召回质量</li><li>能设计短期与长期记忆,处理「对话长了就忘」</li><li>能在有限 token 预算内排布上下文</li></ul><h3 id="常见错误-2" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误-2" aria-label="Permalink to &quot;常见错误&quot;">​</a></h3><ul><li>无脑切固定大小 chunk,不考虑文档结构</li><li>只做向量检索,不做关键词混合,专有名词召回极差</li><li>top_k 设得越大越好,结果引入大量噪声</li><li>记忆只增不减,几天后上下文爆掉</li><li>不知道 lost in the middle,把关键信息放在上下文中间</li></ul><h3 id="晋升标准-2" tabindex="-1">晋升标准 <a class="header-anchor" href="#晋升标准-2" aria-label="Permalink to &quot;晋升标准&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>标准</th></tr></thead><tbody><tr><td>RAG 实现</td><td>独立搭出一个能引用溯源的 RAG 问答系统</td></tr><tr><td>检索优化</td><td>能说出至少 3 种提升召回的方法,并解释各自代价</td></tr><tr><td>记忆设计</td><td>设计一个含摘要与遗忘策略的记忆方案</td></tr><tr><td>上下文管理</td><td>给定 token 预算,能写出优先级排布方案</td></tr></tbody></table><h3 id="考核题型-2" tabindex="-1">考核题型 <a class="header-anchor" href="#考核题型-2" aria-label="Permalink to &quot;考核题型&quot;">​</a></h3><p>概念题(25%) + 方案设计题(35%) + 实操题(40%:基于一批文档做问答,要求给出引用来源)</p><hr><h2 id="level-4-·-资深开发者" tabindex="-1">Level 4 · 资深开发者 <a class="header-anchor" href="#level-4-·-资深开发者" aria-label="Permalink to &quot;Level 4 · 资深开发者&quot;">​</a></h2><h3 id="能力目标-3" tabindex="-1">能力目标 <a class="header-anchor" href="#能力目标-3" aria-label="Permalink to &quot;能力目标&quot;">​</a></h3><ul><li>能实现 ReAct、Plan-and-Execute、反思等主流架构模式</li><li>能用状态机显式控制流程,而不是让模型自由发挥</li><li>能接入人工审批与中断恢复</li><li>能设计降级、重试、熔断等韧性策略</li><li>能识别并防御 Prompt Injection</li><li>能控制单次任务的成本与步数</li></ul><h3 id="常见错误-3" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误-3" aria-label="Permalink to &quot;常见错误&quot;">​</a></h3><ul><li>用自由循环实现一切,流程不可控、不可观测</li><li>没有步数/token 双预算,Agent 陷入死循环烧钱</li><li>所有操作都要求人工确认,失去 Agent 的意义</li><li>重试不区分幂等性,导致重复下单/重复发信</li><li>只防用户输入,不防工具返回的间接注入</li></ul><h3 id="晋升标准-3" tabindex="-1">晋升标准 <a class="header-anchor" href="#晋升标准-3" aria-label="Permalink to &quot;晋升标准&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>标准</th></tr></thead><tbody><tr><td>架构实现</td><td>用 LangGraph 实现一个含条件分支与人审节点的 Agent</td></tr><tr><td>流程控制</td><td>能设计中断/恢复机制,进程重启后任务能续跑</td></tr><tr><td>韧性设计</td><td>给出错误分类表与对应的降级策略</td></tr><tr><td>安全</td><td>能说出 Prompt Injection 的三种注入途径与对应防护</td></tr><tr><td>成本控制</td><td>能设预算并实现超限熔断</td></tr></tbody></table><h3 id="考核题型-3" tabindex="-1">考核题型 <a class="header-anchor" href="#考核题型-3" aria-label="Permalink to &quot;考核题型&quot;">​</a></h3><p>架构设计题(40%) + 故障排查题(30%:给出一个失控/超支的 Agent,定位问题) + 实操题(30%)</p><hr><h2 id="level-5-·-专家-架构师" tabindex="-1">Level 5 · 专家/架构师 <a class="header-anchor" href="#level-5-·-专家-架构师" aria-label="Permalink to &quot;Level 5 · 专家/架构师&quot;">​</a></h2><h3 id="能力目标-4" tabindex="-1">能力目标 <a class="header-anchor" href="#能力目标-4" aria-label="Permalink to &quot;能力目标&quot;">​</a></h3><ul><li>能设计端到端的 Agent 系统架构,并说明每个选型的理由与代价</li><li>能搭建评估体系:分层评估、评测集、LLM-as-Judge、回归测试</li><li>能建立可观测与成本归因,定位慢查询与超支来源</li><li>能设计长时运行任务的持久化与断点续跑</li><li>能主导产品化:信任建立、可控感、预期管理</li><li>能判断「这个需求该不该用 Agent」</li></ul><h3 id="常见错误-4" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误-4" aria-label="Permalink to &quot;常见错误&quot;">​</a></h3><ul><li>只靠感觉调 Prompt,没有评估集,改一处坏三处</li><li>上线后没有 Trace,出问题只能靠用户描述复现</li><li>追求自主程度,不愿意在关键节点加约束</li><li>忽略长尾场景的成本,规模上来后账单失控</li><li>用 Agent 解决本可以写 if-else 的问题</li></ul><h3 id="晋升标准-4" tabindex="-1">晋升标准 <a class="header-anchor" href="#晋升标准-4" aria-label="Permalink to &quot;晋升标准&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>标准</th></tr></thead><tbody><tr><td>系统设计</td><td>给出一个完整生产级 Agent 的架构图与选型论证</td></tr><tr><td>评估体系</td><td>设计出分三层(组件/轨迹/结果)的评估方案</td></tr><tr><td>可观测</td><td>接入 Trace,能按用户/功能维度归因成本</td></tr><tr><td>产品判断</td><td>能论证一个需求该/不该用 Agent,并给出替代方案</td></tr><tr><td>综合交付</td><td>完成第 29 篇综合实战的验收清单</td></tr></tbody></table><h3 id="考核题型-4" tabindex="-1">考核题型 <a class="header-anchor" href="#考核题型-4" aria-label="Permalink to &quot;考核题型&quot;">​</a></h3><p>系统设计题(35%) + 案例分析题(35%:给出一个失败/超支的线上 Agent,给出诊断与改进方案) + 综合实战(30%)</p><hr><h2 id="通用考核说明" tabindex="-1">通用考核说明 <a class="header-anchor" href="#通用考核说明" aria-label="Permalink to &quot;通用考核说明&quot;">​</a></h2><ul><li><strong>不及格的判定</strong>:低于该级最低分,或实操题未完成(实操不及格直接判不通过,笔试高分也不行)</li><li><strong>跨级考核</strong>:允许跳级考,但高级考核会默认你已掌握低级的全部能力</li><li><strong>能力衰减</strong>:Agent 领域迭代极快,建议每 3 个月用当前等级的题型自测一次,尤其关注工具生态(MCP)与模型能力的变化</li></ul>',57)])])}const q=a(r,[["render",i]]);export{b as __pageData,q as default};
